parameters.jsCode:
const input = $input.item.json;
const queryData = $('Generate Research Queries').item.json;

let content = '';
let citations = [];

if (input.choices && input.choices[0]) {
  content = input.choices[0].message?.content || '';
}
if (input.citations) {
  citations = input.citations;
}

const HIGH_AUTHORITY = ['.gov', '.edu', 'nature.com', 'sciencedirect.com', 'pubmed.ncbi', 'arxiv.org', 'hbr.org', 'mckinsey.com'];
const LOW_AUTHORITY = ['reddit.com', 'quora.com', 'medium.com', 'blogspot.com'];

const scoredCitations = citations.map(url => {
  let authority = 1.0;
  const urlLower = (url || '').toLowerCase();
  if (HIGH_AUTHORITY.some(d => urlLower.includes(d))) authority = 2.0;
  else if (LOW_AUTHORITY.some(d => urlLower.includes(d))) authority = 0.5;
  return { url, authority_score: authority };
});

const avgAuthority = scoredCitations.length > 0
  ? scoredCitations.reduce((sum, c) => sum + c.authority_score, 0) / scoredCitations.length
  : 1.0;

return [{
  json: {
    topic: queryData.topic,
    topic_id: queryData.topic_id,
    depth: queryData.depth,
    session_id: queryData.session_id,
    query: queryData.current_query,
    query_category: queryData.query_category,
    response: content,
    citations: scoredCitations,
    average_authority: avgAuthority,
    callback_workflow: queryData.callback_workflow,
    started_at: queryData.started_at
  }
}];

const collectedData = $('Collect All Responses').first().json.data;
const metadata = collectedData[0];
const synthesisRaw = $input.first().json.message?.content || '{}';

let synthesis = {};
try {
  synthesis = typeof synthesisRaw === 'string' ? JSON.parse(synthesisRaw) : synthesisRaw;
} catch (e) {
  synthesis = { summary: synthesisRaw, insights: [], quotes: [], statistics: [], sources: [], key_themes: [] };
}

const insightCount = synthesis.insights?.length || 0;
const quoteCount = synthesis.quotes?.length || 0;
const statCount = synthesis.statistics?.length || 0;
const sourceCount = synthesis.sources?.length || 0;

const qualityScore = Math.min(100,
  (insightCount * 4) + (quoteCount * 8) + (statCount * 6) + (sourceCount * 2) + 20
);

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(metadata.started_at);

const researchId = `research_${metadata.session_id}`;

// Build Markdown document
let markdown = `# Research: ${metadata.topic}\n\n`;
markdown += `**Research ID:** ${researchId}\n`;
markdown += `**Depth:** ${metadata.depth}\n`;
markdown += `**Quality Score:** ${qualityScore}/100\n`;
markdown += `**Generated:** ${completedAt}\n\n`;
markdown += `---\n\n`;

markdown += `## Summary\n\n${synthesis.summary || 'No summary available.'}\n\n`;

if (synthesis.key_themes?.length) {
  markdown += `## Key Themes\n\n`;
  synthesis.key_themes.forEach(theme => {
    markdown += `- ${theme}\n`;
  });
  markdown += `\n`;
}

if (synthesis.insights?.length) {
  markdown += `## Key Insights\n\n`;
  synthesis.insights.forEach((insight, i) => {
    markdown += `### ${i + 1}. ${insight.category?.toUpperCase() || 'INSIGHT'}\n`;
    markdown += `${insight.text}\n`;
    markdown += `*Importance: ${insight.importance}/10*\n\n`;
  });
}

if (synthesis.statistics?.length) {
  markdown += `## Statistics\n\n`;
  synthesis.statistics.forEach(stat => {
    markdown += `- **${stat.stat}** - ${stat.source} (${stat.year})\n`;
  });
  markdown += `\n`;
}

if (synthesis.quotes?.length) {
  markdown += `## Expert Quotes\n\n`;
  synthesis.quotes.forEach(quote => {
    markdown += `> "${quote.text}"\n> — ${quote.author}\n\n`;
  });
}

if (synthesis.sources?.length) {
  markdown += `## Sources\n\n`;
  synthesis.sources.forEach((source, i) => {
    markdown += `${i + 1}. [${source.title}](${source.url}) - *${source.type}*\n`;
  });
  markdown += `\n`;
}

markdown += `---\n\n*Generated by Production Line W5 Research Engine*\n`;

// Create safe filename
const safeTitle = metadata.topic
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 40);
const timestamp = new Date().toISOString().split('T')[0];
const fileName = `${safeTitle}_${timestamp}.md`;
const filePath = `C:/dev/production_line/research/${fileName}`;

const researchPackage = {
  research_id: researchId,
  topic_id: metadata.topic_id,
  topic: metadata.topic,
  session_id: metadata.session_id,
  depth: metadata.depth,
  summary: synthesis.summary || '',
  insights: JSON.stringify(synthesis.insights || []),
  quotes: JSON.stringify(synthesis.quotes || []),
  statistics: JSON.stringify(synthesis.statistics || []),
  sources: JSON.stringify(synthesis.sources || []),
  key_themes: JSON.stringify(synthesis.key_themes || []),
  quality_score: qualityScore,
  insight_count: insightCount,
  quote_count: quoteCount,
  stat_count: statCount,
  source_count: sourceCount,
  file_path: filePath,
  markdown_content: markdown,
  callback_workflow: metadata.callback_workflow,
  started_at: metadata.started_at,
  completed_at: completedAt,
  duration_seconds: Math.round(durationMs / 1000),
  status: 'complete'
};

return [{ json: researchPackage }];

const data = $('Build Research Package').first().json;
const content = data.markdown_content;

// Convert string to binary buffer for file writing
const binaryData = Buffer.from(content, 'utf-8');

return [{
  json: {
    file_path: data.file_path
  },
  binary: {
    data: {
      data: binaryData.toString('base64'),
      mimeType: 'text/markdown',
      fileName: data.file_path.split('/').pop()
    }
  }
}];

const research = $('Build Research Package').first().json;

return [{
  json: {
    success: true,
    research_id: research.research_id,
    topic: research.topic,
    topic_id: research.topic_id,
    depth: research.depth,
    quality: {
      score: research.quality_score,
      grade: research.quality_score >= 80 ? 'A' : research.quality_score >= 60 ? 'B' : 'C'
    },
    metrics: {
      insights: research.insight_count,
      quotes: research.quote_count,
      statistics: research.stat_count,
      sources: research.source_count
    },
    file_path: research.file_path,
    storage: 'n8n_data_table + local_file',
    duration_seconds: research.duration_seconds,
    callback_triggered: !!research.callback_workflow
  }
}];
